// Files & Artifacts. Files: everything uploaded by people or generated by bots.
// Artifacts: documents Claude produced, with versions and export.
import { api, uploadFile, downloadFile, fileBlob, saveBlob } from '../api.js';
import { esc, timeAgo, bytes, toast, modal, icon } from '../ui.js';
import { avatarSVG } from '../avatars.js';
import { markdown } from '../markdown.js';
import { state, botById, go, initials } from '../app.js';
import { openTask } from './tasks.js';

let source = 'all';
let type = '';
let q = '';
let artBot = '';
let pinnedOnly = false;

export function render(main) {
  const tab = state.route.tab === 'artifacts' ? 'artifacts' : 'files';
  const manager = ['owner', 'manager', 'admin'].includes(state.user.role);
  main.innerHTML = `
    <section class="page">
      <header class="view-head">
        <div><h1>Files &amp; Artifacts</h1><p class="muted">${tab === 'files' ? 'Everything you and your bots have uploaded or made' : 'Documents your bots have written, with every version'}</p></div>
        <div class="head-actions">
          <div class="seg" role="tablist">
            <button role="tab" class="${tab === 'files' ? 'on' : ''}" data-tab="files">Files</button>
            <button role="tab" class="${tab === 'artifacts' ? 'on' : ''}" data-tab="artifacts">Artifacts</button>
          </div>
          ${tab === 'files' ? `<button class="btn btn-primary" id="upload">${icon.plus} Upload</button><input type="file" id="upload-input" multiple hidden>` : ''}
        </div>
      </header>
      <div class="toolbar">
        ${tab === 'files' ? `
          <div class="chips">${[['all', 'All'], ['mine', 'Uploaded by you'], ...(manager ? [['team', 'Uploaded by team']] : []), ['bots', 'Generated by bots']].map(([k, l]) => `<button class="chip-btn ${source === k ? 'on' : ''}" data-source="${k}">${l}</button>`).join('')}</div>
          <select id="type" aria-label="File type"><option value="">All types</option>${['document', 'spreadsheet', 'pdf', 'image', 'other'].map((t) => `<option ${type === t ? 'selected' : ''} value="${t}">${t[0].toUpperCase() + t.slice(1)}</option>`).join('')}</select>
          <input id="q" type="search" placeholder="Search files" value="${esc(q)}">` : `
          <select id="art-bot" aria-label="Bot"><option value="">All bots</option>${state.bots.map((b) => `<option value="${b.id}" ${artBot === b.id ? 'selected' : ''}>${esc(b.name)}</option>`).join('')}</select>
          <button class="chip-btn ${pinnedOnly ? 'on' : ''}" id="pinned">${icon.pin} Pinned</button>`}
      </div>
      <div class="page-body" id="lib-body">${tab === 'files' ? filesList() : artifactsGrid()}</div>
    </section>`;

  main.querySelector('.seg').onclick = (e) => { const b = e.target.closest('[data-tab]'); if (b) go({ view: 'library', tab: b.dataset.tab }); };
  if (tab === 'files') {
    main.querySelector('.chips').onclick = (e) => { const b = e.target.closest('[data-source]'); if (b) { source = b.dataset.source; render(main); } };
    main.querySelector('#type').onchange = (e) => { type = e.target.value; render(main); };
    main.querySelector('#q').oninput = (e) => { q = e.target.value; main.querySelector('#lib-body').innerHTML = filesList(); };
    const input = main.querySelector('#upload-input');
    main.querySelector('#upload').onclick = () => input.click();
    input.onchange = async () => {
      for (const f of [...input.files]) { try { await uploadFile(f); } catch (err) { toast(`${f.name}: ${err.message}`, 'danger'); } }
      input.value = '';
    };
  } else {
    main.querySelector('#art-bot').onchange = (e) => { artBot = e.target.value; render(main); };
    main.querySelector('#pinned').onclick = () => { pinnedOnly = !pinnedOnly; render(main); };
  }
  main.querySelector('#lib-body').onclick = onBodyClick;
}

export function onEvent({ type: t }) {
  if (['file', 'file_deleted', 'artifact', 'artifact_deleted', 'bot'].includes(t)) {
    const body = document.getElementById('lib-body');
    if (body) body.innerHTML = state.route.tab === 'artifacts' ? artifactsGrid() : filesList();
  }
}

function filesList() {
  const me = state.user.id;
  const files = state.files.filter((f) => {
    if (source === 'mine' && !(f.source === 'upload' && f.uploaded_by === me)) return false;
    if (source === 'team' && !(f.source === 'upload' && f.uploaded_by !== me)) return false;
    if (source === 'bots' && f.source !== 'bot') return false;
    if (type && f.type !== type) return false;
    if (q && !f.name.toLowerCase().includes(q.toLowerCase())) return false;
    return true;
  });
  if (!files.length) return `<div class="empty">${source === 'bots' ? 'Your bots haven\'t made any files yet.' : 'No files yet. Upload one, or drop files into a chat.'}</div>`;
  const canDelete = ['owner', 'manager', 'admin'].includes(state.user.role);
  return `<div class="table files">
    <div class="tr th"><span>Name</span><span>From</span><span>Task</span><span>Size</span><span>Added</span><span></span></div>
    ${files.map((f) => {
      const bot = botById(f.bot_id);
      const from = f.source === 'bot'
        ? `<span class="tile-bot">${bot ? avatarSVG(bot.avatar, 20) : ''}${esc(bot?.name || 'Bot')}</span>`
        : `<span class="tile-bot"><span class="me-avatar sm">${esc(initials(f.uploaded_by_name || (f.uploaded_by === me ? state.user.name : '?')))}</span>${f.uploaded_by === me ? 'You' : esc(f.uploaded_by_name || 'Teammate')}</span>`;
      return `<div class="tr">
        <span class="file-name"><span class="ftype ftype-${f.type}">${icon.file}</span>${esc(f.name)}</span>
        <span>${from}</span>
        <span>${f.task_id ? `<button class="link mono" data-task="${f.task_id}">${esc(f.task_id)}</button>` : '<span class="muted">—</span>'}</span>
        <span class="muted">${bytes(f.size)}</span>
        <span class="muted">${timeAgo(f.created_at)}</span>
        <span class="row-actions">
          <button class="btn btn-sm" data-preview="${f.id}">Preview</button>
          <button class="btn btn-sm" data-download="${f.id}">Download</button>
          <button class="btn btn-sm" data-ask="${f.id}" title="Open a chat with this file attached">Ask a bot</button>
          ${canDelete ? `<button class="icon-btn" data-delete-file="${f.id}" aria-label="Delete">${icon.x}</button>` : ''}
        </span>
      </div>`;
    }).join('')}
  </div>`;
}

function artifactsGrid() {
  const arts = state.artifacts.filter((a) => (!artBot || a.bot_id === artBot) && (!pinnedOnly || a.pinned));
  if (!arts.length) return '<div class="empty">No artifacts yet. Ask a bot for a report, proposal or brief and it lands here.</div>';
  return `<div class="art-grid">${arts.map((a) => {
    const bot = botById(a.bot_id);
    return `<button class="art-card" data-open-artifact="${a.id}">
      <div class="art-thumb md">${markdown(a.preview || '')}</div>
      <div class="art-info">
        <div class="art-title">${a.pinned ? `<span class="pin">${icon.pin}</span>` : ''}${esc(a.title)}</div>
        <div class="art-meta">${bot ? `<span class="tile-bot">${avatarSVG(bot.avatar, 18)}${esc(bot.name)}</span>` : ''}<span class="chip chip-neutral">${esc(a.kind)}</span><span class="mono muted">v${a.version}</span><span class="muted">${timeAgo(a.updated_at)}</span></div>
      </div>
    </button>`;
  }).join('')}</div>`;
}

async function onBodyClick(e) {
  const b = e.target.closest('button');
  if (!b) return;
  const file = (id) => state.files.find((f) => f.id === id);
  try {
    if (b.dataset.task) return openTask(b.dataset.task);
    if (b.dataset.openArtifact) return openArtifact(b.dataset.openArtifact);
    if (b.dataset.download) return downloadFile(file(b.dataset.download));
    if (b.dataset.preview) return previewFile(file(b.dataset.preview));
    if (b.dataset.ask) return askAbout(file(b.dataset.ask));
    if (b.dataset.deleteFile) {
      await api('DELETE', `/api/files/${b.dataset.deleteFile}`);
      toast('Moved to trash (kept for 30 days)');
    }
  } catch (err) { toast(err.message, 'danger'); }
}

async function previewFile(f) {
  const blob = await fileBlob(f);
  let body;
  if (f.type === 'image') body = `<img class="preview-img" src="${URL.createObjectURL(blob)}" alt="">`;
  else if (f.type === 'pdf') body = `<iframe class="preview-pdf" src="${URL.createObjectURL(blob)}"></iframe>`;
  else if (/^text\/|json|csv|markdown/.test(f.mime) || /\.(csv|md|txt|json)$/i.test(f.name)) {
    const text = await blob.text();
    body = /\.csv$/i.test(f.name) ? csvTable(text) : /\.md$/i.test(f.name) ? `<div class="md">${markdown(text)}</div>` : `<pre class="preview-text">${esc(text.slice(0, 20000))}</pre>`;
  } else body = '<div class="empty">No preview for this file type. Download it to open it.</div>';
  const m = modal(`<div class="modal-head"><h2>${esc(f.name)}</h2><button class="icon-btn" data-close aria-label="Close">${icon.x}</button></div><div class="preview">${body}</div>`, { wide: true });
  m.el.querySelector('[data-close]').onclick = m.close;
}

function csvTable(text) {
  const rows = text.trim().split(/\r?\n/).slice(0, 200).map((r) => r.split(','));
  return `<div class="md"><table><thead><tr>${rows[0].map((c) => `<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.slice(1).map((r) => `<tr>${r.map((c) => `<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}

function askAbout(f) {
  const m = modal(`<h2>Ask a bot about ${esc(f.name)}</h2><div class="pick-bots">${state.bots.map((b) => `<button class="bot-row" data-bot="${b.id}"><span class="bot-face">${avatarSVG(b.avatar, 36)}</span><span class="bot-meta"><span class="bot-name">${esc(b.name)}</span><span class="bot-status">${esc(b.description)}</span></span></button>`).join('')}</div>`);
  m.el.onclick = async (e) => {
    const b = e.target.closest('[data-bot]');
    if (!b) return;
    m.close();
    go({ view: 'chat', botId: b.dataset.bot });
    await api('POST', `/api/bots/${b.dataset.bot}/messages`, { text: `Take a look at ${f.name} and tell me what's important in it.`, file_ids: [f.id] });
  };
}

export async function openArtifact(id) {
  let art = await api('GET', `/api/artifacts/${id}`);
  let shown = art.versions[0];
  const m = modal('<div id="art-view" class="art-view"></div>', { wide: true });
  const draw = () => {
    const bot = botById(art.bot_id);
    m.el.querySelector('#art-view').innerHTML = `
      <div class="modal-head">
        <div><h2>${esc(art.title)}</h2><div class="art-meta">${bot ? `<span class="tile-bot">${avatarSVG(bot.avatar, 18)}${esc(bot.name)}</span>` : ''}<span class="chip chip-neutral">${esc(art.kind)}</span>${art.task_id ? `<button class="link mono" data-task="${art.task_id}">${esc(art.task_id)}</button>` : ''}</div></div>
        <button class="icon-btn" data-close aria-label="Close">${icon.x}</button>
      </div>
      <div class="art-layout">
        <article class="md art-doc" id="art-doc">${markdown(shown.content)}</article>
        <aside class="art-side">
          <div class="art-buttons">
            <button class="btn" data-pin>${icon.pin} ${art.pinned ? 'Unpin' : 'Pin'}</button>
            <button class="btn" data-edit>Edit</button>
            <button class="btn" data-refine>Refine with bot</button>
            <button class="btn" data-export="md">Export .md</button>
            <button class="btn" data-export="html">Export .html</button>
            <button class="btn" data-print>Print / PDF</button>
          </div>
          <h3>Versions</h3>
          <ol class="versions">${art.versions.map((v) => `<li><button class="link ${v.id === shown.id ? 'on' : ''}" data-version="${v.id}">v${v.version}</button> <span class="muted small">${esc(v.note || '')} · ${timeAgo(v.created_at)}</span></li>`).join('')}</ol>
        </aside>
      </div>`;
  };
  draw();
  m.el.addEventListener('click', async (e) => {
    const b = e.target.closest('button');
    if (!b) return;
    if (b.hasAttribute('data-close')) return m.close();
    if (b.dataset.task) { m.close(); return openTask(b.dataset.task); }
    if (b.dataset.version) { shown = art.versions.find((v) => v.id === b.dataset.version); return draw(); }
    if (b.hasAttribute('data-pin')) { art = await api('PATCH', `/api/artifacts/${art.id}`, { pinned: !art.pinned }); shown = art.versions.find((v) => v.id === shown.id) || art.versions[0]; return draw(); }
    if (b.dataset.export) {
      const name = art.title.replace(/[^\w\- ]+/g, '').trim() || 'artifact';
      return b.dataset.export === 'md'
        ? saveBlob(new Blob([shown.content], { type: 'text/markdown' }), `${name}.md`)
        : saveBlob(new Blob([`<!doctype html><meta charset="utf-8"><title>${esc(art.title)}</title><body style="font-family:Archivo,Arial,sans-serif;max-width:760px;margin:40px auto;line-height:1.55">${markdown(shown.content)}</body>`], { type: 'text/html' }), `${name}.html`);
    }
    if (b.hasAttribute('data-print')) {
      // A hidden frame prints just the document (Windows offers "Save as PDF").
      const frame = document.createElement('iframe');
      frame.style.cssText = 'position:fixed;width:0;height:0;border:0';
      document.body.appendChild(frame);
      frame.contentDocument.write(`<title>${esc(art.title)}</title><body style="font-family:Arial,sans-serif;max-width:760px;margin:40px auto;line-height:1.55">${markdown(shown.content)}</body>`);
      frame.contentDocument.close();
      frame.contentWindow.print();
      setTimeout(() => frame.remove(), 1000);
      return;
    }
    if (b.hasAttribute('data-refine') && art.bot_id) {
      m.close();
      go({ view: 'chat', botId: art.bot_id });
      return;
    }
    if (b.hasAttribute('data-edit')) {
      const doc = m.el.querySelector('#art-doc');
      doc.outerHTML = `<form class="art-doc form" id="art-edit"><textarea name="content" rows="22">${esc(shown.content)}</textarea><input name="note" placeholder="What did you change? (optional)"><div class="modal-actions"><button type="button" class="btn btn-ghost" data-cancel-edit>Cancel</button><button class="btn btn-primary" type="submit">Save as v${art.versions[0].version + 1}</button></div></form>`;
      const form = m.el.querySelector('#art-edit');
      form.querySelector('[data-cancel-edit]').onclick = draw;
      form.onsubmit = async (ev) => {
        ev.preventDefault();
        const fd = new FormData(form);
        art = await api('POST', `/api/artifacts/${art.id}/versions`, { content: fd.get('content'), note: fd.get('note') });
        shown = art.versions[0];
        draw();
        toast(`Saved v${shown.version}`, 'success');
      };
    }
  });
}
